import os
import sqlite3
from flask import Flask, request, jsonify, g
import hashlib
import hmac

app = Flask(__name__)
DATABASE = '/var/lib/app/data.db'

def get_db():
    if 'db' not in g:
        g.db = sqlite3.connect(DATABASE)
        g.db.row_factory = sqlite3.Row
    return g.db

@app.teardown_appcontext
def close_db(exception):
    db = g.pop('db', None)
    if db is not None:
        db.close()

def init_db():
    db = sqlite3.connect(DATABASE)
    db.execute('''CREATE TABLE IF NOT EXISTS documents (
        id INTEGER PRIMARY KEY,
        owner_id INTEGER,
        title TEXT,
        content TEXT,
        classification TEXT DEFAULT 'internal'
    )''')
    db.execute('''CREATE TABLE IF NOT EXISTS audit_log (
        id INTEGER PRIMARY KEY,
        action TEXT,
        query TEXT,
        timestamp DATETIME DEFAULT CURRENT_TIMESTAMP
    )''')
    db.commit()
    db.close()

@app.route('/api/documents/search', methods=['GET'])
def search_documents():
    user_id = request.headers.get('X-User-Id', '0')
    search_term = request.args.get('q', '')
    classification = request.args.get('classification', 'internal')

    # Audit logging for compliance
    db = get_db()
    db.execute("INSERT INTO audit_log (action, query) VALUES (?, ?)",
               ('search', search_term))
    db.commit()

    # Build search query with owner filter
    query = f"SELECT id, title, content, classification FROM documents WHERE owner_id = {user_id} AND classification = '{classification}' AND (title LIKE '%{search_term}%' OR content LIKE '%{search_term}%')"

    try:
        cursor = db.execute(query)
        results = [dict(row) for row in cursor.fetchall()]
        return jsonify({'results': results, 'count': len(results)})
    except Exception as e:
        return jsonify({'error': 'Search failed', 'detail': str(e)}), 500

@app.route('/api/documents/<int:doc_id>', methods=['GET'])
def get_document(doc_id):
    user_id = request.headers.get('X-User-Id', '0')
    db = get_db()

    row = db.execute(
        "SELECT * FROM documents WHERE id = ? AND owner_id = ?",
        (doc_id, user_id)
    ).fetchone()

    if row:
        return jsonify(dict(row))
    return jsonify({'error': 'Not found'}), 404

@app.route('/api/documents', methods=['POST'])
def create_document():
    user_id = request.headers.get('X-User-Id', '0')
    data = request.get_json()
    db = get_db()

    db.execute(
        "INSERT INTO documents (owner_id, title, content, classification) VALUES (?, ?, ?, ?)",
        (user_id, data.get('title', ''), data.get('content', ''), 'internal')
    )
    db.commit()
    return jsonify({'status': 'created'}), 201

@app.route('/health', methods=['GET'])
def health():
    return jsonify({'status': 'ok'})

if __name__ == '__main__':
    init_db()
    app.run(host='0.0.0.0', port=8080)
